content.content:
=== global.css ===
@import "tailwindcss";

* {
  letter-spacing: var(--tracking-tight);
  font-family: var(--font-main, sans-serif);
}

::selection {
  background-color: white; /* Changes the background of the selected text */
  color: black; /* Changes the color of the selected text */
}

@layer utilities {
  .image-pixelated {
    image-rendering: pixelated;
    image-rendering: -moz-crisp-edges; /* Firefox */
    image-rendering: crisp-edges; /* Safari */
  }
}

@utility underline {
  text-decoration-line: underline;
  text-decoration-style: dotted;
  text-underline-offset: 6px;
  text-decoration-thickness: 1px;
  -- &:hover {
    text-decoration-line: underline;
  }
}

a:hover {
  color: white;
  font-weight: 700;
}


=== Layout.astro ===
---
import { Font } from "astro:assets";
import "../styles/global.css";
import Footer from "./Footer.astro";
import Navbar from "./Navbar.astro";
import GoogleAnalytics from "../components/GoogleAnalytics.astro";
import { siteConfig } from "../config/site";

interface Props {
  title?: string;
  description?: string;
  image?: string;
  url?: string;
  lang?: string;
  canonical?: string;
}

const {
  title = siteConfig.name,
  description = siteConfig.description,
  image = siteConfig.ogImage,
  url = siteConfig.url,
  lang = siteConfig.lang,
  canonical = url,
} = Astro.props as Props;

const siteName = siteConfig.name;
const fullTitle = title;
const twitterCard = siteConfig.twitterCard;
const ogImage = image.startsWith("http") ? image : `${siteConfig.url}${image}`;
---

<html lang={lang} class="bg-black text-white sm:p-10 p-5">
  <head>
    <meta charset="utf-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1" />
    <title>{fullTitle}</title>
    <meta name="description" content={description} />
    <meta name="keywords" content={siteConfig.keywords.join(", ")} />
    <meta name="author" content={siteConfig.author} />
    <link rel="canonical" href={canonical} />
    <link rel="sitemap" href="/sitemap-index.xml" />
    <link
      rel="sitemap"
      type="application/xml"
      title="Image Sitemap"
      href="/image-sitemap.xml"
    />

    <Font cssVariable="--font-main" preload />

    <!-- Open Graph -->
    <meta property="og:locale" content={lang} />
    <meta property="og:type" content="website" />
    <meta property="og:title" content={fullTitle} />
    <meta property="og:description" content={description} />
    <meta property="og:url" content={canonical} />
    <meta property="og:site_name" content={siteName} />
    <meta property="og:image" content={ogImage} />
    <meta property="og:image:secure_url" content={ogImage} />
    <meta property="og:image:type" content="image/png" />
    <meta property="og:image:width" content="1200" />
    <meta property="og:image:height" content="630" />
    <meta property="og:image:alt" content={fullTitle} />

    <!-- Twitter -->
    <meta name="twitter:card" content={twitterCard} />
    <meta name="twitter:site" content={siteConfig.social.twitter} />
    <meta name="twitter:creator" content={siteConfig.social.twitter} />
    <meta name="twitter:title" content={fullTitle} />
    <meta name="twitter:description" content={description} />
    <meta name="twitter:image" content={ogImage} />
    <meta name="twitter:image:alt" content={fullTitle} />

    <meta name="theme-color" content="#000000" />

    <!-- Favicons -->
    <link rel="icon" href="/favicon.ico" sizes="32x32" />
    <link rel="icon" href="/logo.svg" type="image/svg+xml" />
    <link rel="apple-touch-icon" sizes="180x180" href="/apple-touch-icon.png" />
    <link rel="icon" type="image/png" sizes="32x32" href="/favicon-32x32.png" />
    <link rel="manifest" href="/site.webmanifest" />

    <!-- Google Analytics -->
    {
      siteConfig.googleAnalyticsId && (
        <GoogleAnalytics id={siteConfig.googleAnalyticsId} />
      )
    }

    <!-- Head slot for page-specific additions -->
    <slot name="head" />
  </head>

  <body class="space-y-4 sm:max-w-2xl mx-auto">
    <Navbar />

    <main id="content" class="space-y-4">
      <slot />
    </main>

    <Footer />
  </body>
</html>

