  }
  .row > .cell + .cell {
    padding-left: 0;
    border-left: 0;
    margin-top: 30px;
    padding-top: 30px;
    border-top: 1px solid var(--line-soft);
  }
  .cell.media {
    order: 2;
  }
}

/* ============================================================
   spec list (dotted leaders)
   ============================================================ */
.specs {
  margin-top: 30px;
  display: flex;
  flex-direction: column;
  gap: 11px;
  max-width: 54ch;
}
.spec {
  display: flex;
  align-items: baseline;
  font-size: 14px;
}
.spec .k {
  font-family: var(--ff-display);
  letter-spacing: 0.03em;
  color: var(--fg-soft);
  white-space: nowrap;
}
.spec .dots {
  flex: 1;
  margin: 0 10px;
  border-bottom: 1px dotted rgba(255, 255, 255, 0.22);
  transform: translateY(-4px);
  transition: border-color 0.15s;
}
.spec .v {
  color: var(--meta);
  white-space: nowrap;
  transition: color 0.15s;
}
.spec:hover .v {
  color: var(--fg);
}
.spec:hover .dots {
  border-color: rgba(255, 255, 255, 0.5);
}

/* ---- redacted / classified ---- */
.redacted {
  display: inline-block;
  color: transparent;
  background: rgba(255, 255, 255, 0.16);
  border-radius: 1px;
  user-select: none;
  letter-spacing: 0;
}

/* ============================================================
   image frames (placeholder + real)
   ============================================================ */
.frame-fig {
  position: relative;
  width: 100%;
}
.frame-fig .box {
  position: relative;
  width: 100%;
  min-height: 200px;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  border: 1px dashed var(--line);
  color: var(--meta);
  font-size: 12px;
  letter-spacing: 0.08em;
  background: repeating-linear-gradient(
    45deg,
    transparent 0 12px,
    rgba(255, 255, 255, 0.015) 12px 13px
  );
}
.frame-fig .box.tall {
  min-height: 300px;
}
.frame-fig .box.wide {
  min-height: 220px;
}
.frame-fig .box img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: contain;
}
/* corner ticks */
.frame-fig .box::before,
.frame-fig .box::after {
  content: "";
  position: absolute;
  width: 8px;
  height: 8px;
  border: 1px solid rgba(255, 255, 255, 0.3);
  pointer-events: none;
}
.frame-fig .box::before {
  top: -1px;
  left: -1px;
  border-right: 0;
  border-bottom: 0;
}
.frame-fig .box::after {
  bottom: -1px;
  right: -1px;
  border-left: 0;
  border-top: 0;
}
.frame-fig figcaption {
  margin-top: 8px;
  font-family: var(--ff-display);
  font-size: 11px;
  letter-spacing: 0.05em;
  color: var(--meta);
}

/* ============================================================
   connection (climax) + full-bleed
   ============================================================ */
.fullbleed {
  width: 100vw;
  margin-left: calc(50% - 50vw);
}
.connect .stack {
  display: flex;
  flex-direction: column;
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
}
.connect .stack .frame-fig .box {
  border: 0;
}
.connect .stack .frame-fig + .frame-fig .box {
  border-top: 1px solid var(--line);
}
.payoff {
  max-width: 54ch;
  margin: 56px auto 0;
  text-align: center;
  font-size: 19px;
  line-height: 1.6;
  color: var(--fg-soft);
}
.payoff .last {
  display: block;
  margin-top: 26px;
  font-family: var(--ff-display);
  font-size: 21px;
  letter-spacing: 0.01em;
  color: var(--fg);
}

/* ============================================================
   close + footer
   ============================================================ */
blockquote {
  max-width: 52ch;
  font-style: italic;
  font-size: 16px;
  line-height: 1.6;
  color: var(--meta);
}
blockquote cite {
  display: block;
  margin-top: 10px;
  font-style: normal;
  color: var(--fg-soft);
}
.contact {
  margin-top: 40px;
}
.contact .links {
  margin-top: 18px;
  display: flex;
  gap: 18px;
  font-size: 14px;
}

.footer {
  position: relative;
  border-top: 1px solid var(--line);
  padding: 44px var(--pad-x) 36px;
}
.footer::before,
.footer::after {
  content: "+";
  position: absolute;
  top: 0;
  font-size: 11px;
  line-height: 1;
  color: rgba(255, 255, 255, 0.3);
  pointer-events: none;
}
.footer::before {
  left: 0;
  transform: translate(-50%, -50%);
}
.footer::after {
  right: 0;
  transform: translate(50%, -50%);
}
.footer .braille {
  font-family: var(--ff-body);
  font-size: 7px;
  line-height: 1;
  white-space: pre;
  overflow: hidden;
  color: rgba(255, 255, 255, 0.1);
  margin-bottom: 28px;
}
.footer .foot-row {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 16px;
}
.footer .version {
  font-family: var(--ff-display);
  font-size: 11px;
  letter-spacing: 0.08em;
  color: var(--meta);
}
.footer .copyright {
  font-size: 12px;
  color: var(--meta);
}

/* ============================================================
   fixed overlays — crop-marks · vignette · grain
   ============================================================ */
.cropmarks,
.vignette,
.grain {
  position: fixed;
  inset: 0;
  pointer-events: none;
}
.cropmarks {
  z-index: 65;
}
.cropmarks span {
  position: fixed;
  width: 13px;
  height: 13px;
}
.cropmarks span:nth-child(1) {
  top: 16px;
  left: 16px;
  border-top: 1px solid rgba(255, 255, 255, 0.25);
  border-left: 1px solid rgba(255, 255, 255, 0.25);
}
.cropmarks span:nth-child(2) {
  top: 16px;
  right: 16px;
  border-top: 1px solid rgba(255, 255, 255, 0.25);
  border-right: 1px solid rgba(255, 255, 255, 0.25);
}
.cropmarks span:nth-child(3) {
  bottom: 16px;
  left: 16px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.25);
  border-left: 1px solid rgba(255, 255, 255, 0.25);
}
.cropmarks span:nth-child(4) {
  bottom: 16px;
  right: 16px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.25);
  border-right: 1px solid rgba(255, 255, 255, 0.25);
}
.vignette {
  z-index: 55;
  background: radial-gradient(
    ellipse at center,
    transparent 52%,
    rgba(0, 0, 0, 0.55) 100%
  );
}
.grain {
  z-index: 60;
  opacity: 0.035;
  background-image: url("data:image/svg+xml,%3Csvg%20xmlns='http://www.w3.org/2000/svg'%20width='160'%20height='160'%3E%3Cfilter%20id='n'%3E%3CfeTurbulence%20type='fractalNoise'%20baseFrequency='0.9'%20numOctaves='2'%20stitchTiles='stitch'/%3E%3C/filter%3E%3Crect%20width='100%25'%20height='100%25'%20filter='url(%23n)'/%3E%3C/svg%3E");
}

/* ============================================================
   utilities + a11y
   ============================================================ */
@layer utilities {
  .image-pixelated {
    image-rendering: pixelated;
    image-rendering: -moz-crisp-edges;
    image-rendering: crisp-edges;
  }
}

@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }
  *,
  *::before,
  *::after {
    transition: none !important;
    animation: none !important;
  }
}

