---
// src/pages/index.astro
import { Image } from "astro:assets";
import { ArrowRight } from "lucide-react";
import { siteConfig } from "../config/site";
import Layout from "../layouts/Layout.astro";

const canonicalURL = new URL(Astro.url.pathname, siteConfig.url).href;

const meta = {
  title: "the experience company",
  description:
    "We're a team of hackers, engineers, and designers behind products like GAIA. Creating technology that improves everyday lives.",
  image: `${siteConfig.url}/og-image.webp`,
  url: canonicalURL,
  canonical: canonicalURL,
};

const projects = [
  {
    logo: "/gaia.webp",
    name: "GAIA",
    url: "https://heygaia.io",
    description: "Personal AI assistant",
    status: "Live",
    category: "Artificial Intelligence",
  },
  {
    name: "",
    url: null,
    description: "next-gen wearables",
    status: "upcoming",
    category: "Wearable Technology",
  },
  {
    name: "",
    url: null,
    description: "Household robotics",
    status: "upcoming",
    category: "Robotics",
  },
];

const organizationSchema = {
  "@context": "https://schema.org",
  "@type": "Organization",
  "@id": `${siteConfig.url}/#organization`,
  name: siteConfig.name,
  alternateName: "Experience Company",
  url: siteConfig.url,
  logo: {
    "@type": "ImageObject",
    url: `${siteConfig.url}/logo.svg`,
    width: 512,
    height: 512,
  },
  description: meta.description,
  foundingDate: "2023",
  foundingLocation: {
    "@type": "Place",
    name: "Global",
  },
  areaServed: {
    "@type": "Place",
    name: "Worldwide",
  },
  slogan: "Building Technology That Matters",
  knowsAbout: [
    "Artificial Intelligence",
    "Software Development",
    "Product Design",
    "Wearable Technology",
    "Robotics",
    "User Experience Design",
  ],
  contactPoint: {
    "@type": "ContactPoint",
    contactType: "General Inquiries",
    email: siteConfig.social.email,
    availableLanguage: ["en"],
  },
  sameAs: [
    `https://twitter.com/${siteConfig.social.twitter?.replace("@", "")}`,
    `https://github.com/${siteConfig.social.github}`,
  ],
};

const webPageSchema = {
  "@context": "https://schema.org",
  "@type": "WebPage",
  "@id": `${canonicalURL}#webpage`,
  url: canonicalURL,
  name: meta.title,
  description: meta.description,
  inLanguage: "en-US",
  isPartOf: {
    "@type": "WebSite",
    "@id": `${siteConfig.url}/#website`,
    url: siteConfig.url,
    name: siteConfig.name,
    publisher: {
      "@id": `${siteConfig.url}/#organization`,
    },
  },
  about: {
    "@id": `${siteConfig.url}/#organization`,
  },
  primaryImageOfPage: {
    "@type": "ImageObject",
    "@id": `${meta.image}#image`,
    url: meta.image,
    contentUrl: meta.image,
    width: 1200,
    height: 630,
    caption: meta.description,
    inLanguage: "en-US",
    license: siteConfig.url,
  },
  datePublished: "2023-01-01T00:00:00+00:00",
  dateModified: new Date().toISOString(),
};

// Enhanced image schema for OG image
const ogImageSchema = {
